<?php require __DIR__.'/config.php';$u=require_login();if(is_super_admin())redirect('admin.php');$b=require_business();if(!can('reports')){http_response_code(403);exit('Forbidden');}$pdo=db();$range=$_GET['range']??'today';$from=$range==='week'?date('Y-m-d',strtotime('monday this week')):($range==='month'?date('Y-m-01'):($range==='year'?date('Y-01-01'):date('Y-m-d')));$to=date('Y-m-d H:i:s');$s=$pdo->prepare("SELECT COALESCE(SUM(total),0) sales,COUNT(*) orders,SUM(status IN ('completed','served')) completed,SUM(status='cancelled') cancelled FROM orders WHERE business_id=? AND created_at>=? AND created_at<=?");$s->execute([$b['id'],$from.' 00:00:00',$to]);$r=$s->fetch();$st=$pdo->prepare("SELECT u.name,COUNT(*) served,COALESCE(SUM(o.total),0) value FROM orders o JOIN users u ON u.id=o.served_by WHERE o.business_id=? AND o.served_by IS NOT NULL AND o.created_at>=? AND o.created_at<=? GROUP BY o.served_by ORDER BY served DESC");$st->execute([$b['id'],$from.' 00:00:00',$to]);$staff=$st->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow">Analytics</div><h1>Business pulse</h1><p>Sales and staff performance.</p></div></div><div class="seg"><a class="<?= $range==='today'?'active':''?>" href="?range=today">Today</a><a class="<?= $range==='week'?'active':''?>" href="?range=week">Week</a><a class="<?= $range==='month'?'active':''?>" href="?range=month">Month</a><a class="<?= $range==='year'?'active':''?>" href="?range=year">Year</a></div><div class="stats"><div class="panel"><span>Sales</span><strong><?=money((float)$r['sales'])?></strong></div><div class="panel"><span>Orders</span><strong><?=number_format((int)$r['orders'])?></strong></div><div class="panel"><span>Completed</span><strong><?=number_format((int)$r['completed'])?></strong></div><div class="panel"><span>Cancelled</span><strong><?=number_format((int)$r['cancelled'])?></strong></div></div><div class="panel"><h3>Staff who served customers</h3><?php foreach($staff as $x):?><div class="row"><div><b><?=e($x['name'])?></b><div class="small muted"><?=number_format((int)$x['served'])?> completed orders</div></div><b><?=money((float)$x['value'])?></b></div><?php endforeach;if(!$staff):?><p class="muted">No served orders in this period yet.</p><?php endif;?></div><?php include __DIR__.'/app/layout_bottom.php';
